package com.hms.waitlist;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="appointment_waitlist") public class WaitlistEntry { @Id private UUID id; @Column(nullable=false) private UUID tenantId; @Column(nullable=false) private UUID patientId; @Column(nullable=false) private UUID doctorId; @Column(nullable=false) private LocalDate requestedDate; @Column(length=500) private String reason; @Column(nullable=false) private boolean priority; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private WaitlistStatus status; @Column(nullable=false) private OffsetDateTime createdAt; @Column(nullable=false) private OffsetDateTime updatedAt; protected WaitlistEntry(){} public WaitlistEntry(UUID tenantId,UUID patientId,UUID doctorId,LocalDate date,String reason,boolean priority){this.id=UUID.randomUUID();this.tenantId=tenantId;this.patientId=patientId;this.doctorId=doctorId;this.requestedDate=date;this.reason=reason;this.priority=priority;this.status=WaitlistStatus.WAITING;this.createdAt=OffsetDateTime.now();this.updatedAt=createdAt;} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public UUID getPatientId(){return patientId;} public UUID getDoctorId(){return doctorId;} public LocalDate getRequestedDate(){return requestedDate;} public String getReason(){return reason;} public boolean isPriority(){return priority;} public WaitlistStatus getStatus(){return status;} public void updateStatus(WaitlistStatus next){if(status==WaitlistStatus.BOOKED||status==WaitlistStatus.CANCELLED)throw new IllegalArgumentException("Waitlist entry is closed");status=next;updatedAt=OffsetDateTime.now();}}
